"274 :     @Override
275 :     public Date parse(String source, ParsePosition pos) {
276 :         int offset= pos.getIndex();
277 :         Matcher matcher= parsePattern.matcher(source.substring(offset));
278 :         if(!matcher.lookingAt()) {
279 :             return null;
280 :         }
281 :         // timing tests indicate getting new instance is 19% faster than cloning
282 :         Calendar cal= Calendar.getInstance(timeZone, locale);
283 :         cal.clear();
284 : 
285 :         for(int i=0; i<strategies.length;) {
286 :             Strategy strategy= strategies[i++];
287 :             strategy.setCalendar(this, cal, matcher.group(i));
288 :         }
289 :         pos.setIndex(offset+matcher.end());
290 :         return cal.getTime();
291 :     }"

